"""Offline product-strategy view; preserve the analytical data and its evidence limits."""
import json


def render_strategy_report(data):
    """Render provenance-bearing strategy data without supplying missing quantities."""
    if not isinstance(data, dict):
        raise ValueError('Strategy report data must be an object')
    payload = json.dumps(data, ensure_ascii=True, sort_keys=True,
                         separators=(',', ':'), allow_nan=False)
    payload = payload.replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return _PAGE.replace('/*__STRATEGY_DATA__*/', payload) + '\n'


